using Android;
using Android.App;
using Android.Content.PM;
using Codex.Domain.Plate;

// The Paper & Ink launcher icon (generated by Tools/IconStudio) is set on the
// [Application] attribute of PlateApplication; the manifest cannot carry both
// a class-level and an assembly-level Application element (error XAGMM7009).

// CAMERA is a sensor permission and cannot be silently granted by the device
// owner; it is granted once via the runtime dialog at cutover.
[assembly: UsesPermission(Manifest.Permission.Camera)]
[assembly: UsesFeature("android.hardware.camera.any", Required = true)]

// Needed to launch Google Photos (GetLaunchIntentForPackage) under Android 11+
// package-visibility filtering. Sideloaded app, so QUERY_ALL_PACKAGES is fine.
[assembly: UsesPermission(Manifest.Permission.QueryAllPackages)]

// The vault and the reMarkable are both network. Nothing Plate captures leaves the phone
// by this route without the owner choosing a destination first.
[assembly: UsesPermission(Manifest.Permission.Internet)]

// Sound on a video. A sensor permission, so it is asked for at the runtime dialog like
// CAMERA; refused, a recording still runs, silently, rather than refusing to start.
[assembly: UsesPermission(Manifest.Permission.RecordAudio)]

// The Rolodex: names for the faces Plate finds, and the contact photos it learns them from.
// Read-only, and nothing it reads leaves the phone.
[assembly: UsesPermission(Manifest.Permission.ReadContacts)]

// Constitution's recipe read (PBI C-11.2.1). The permission is Plate's to declare and Constitution's to hold; at
// signature level it costs nothing, since every head shares one keystore for the update channel, and without it any
// app on the phone could start a read. Constitution must be installed after Plate carries this declaration, or its
// uses-permission is not granted until it is reinstalled.
[assembly: Permission(Name = ReadRequest.RecipePermission, ProtectionLevel = Protection.Signature)]
